inline bool InRing(const Ring& ring,double x,double y) {
    bool inside=false;
    for (std::size_t i=0,j=ring.count-1;i<ring.count;j=i++) {
        const auto a=kPoints[ring.first+i],b=kPoints[ring.first+j];
        if ((a.y>y)!=(b.y>y) && x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x) inside=!inside;
    }
    return inside;
}
inline double CoastDistanceSquared(const Ring& ring,double longitude,double latitude,double scale) {
    double nearest=std::numeric_limits<double>::infinity();
    for (std::size_t i=0,j=ring.count-1;i<ring.count;j=i++) {
        const auto a=kPoints[ring.first+i],b=kPoints[ring.first+j];
        const double ax=(a.x-longitude)*scale,ay=(a.y-latitude)*111320.0;
        const double bx=(b.x-longitude)*scale,by=(b.y-latitude)*111320.0;
        const double dx=bx-ax,dy=by-ay,length=dx*dx+dy*dy;
        const double t=length>0?std::clamp(-(ax*dx+ay*dy)/length,0.0,1.0):0.0;
        const double px=ax+t*dx,py=ay+t*dy;
        nearest=std::min(nearest,px*px+py*py);
    }
    return nearest;
}
inline std::string_view AreaAt(double longitude,double latitude) {
    if (!std::isfinite(longitude)||!std::isfinite(latitude)||longitude < -180||longitude > 180||latitude < -90||latitude > 90) return {};
    for (const auto& polygon:kPolygons) {
        if (longitude<polygon.west||longitude>polygon.east||latitude<polygon.south||latitude>polygon.north) continue;
        if (!InRing(kRings[polygon.firstRing],longitude,latitude)) continue;
        bool hole=false;
        for (std::size_t i=1;i<polygon.ringCount;++i)
            if (InRing(kRings[polygon.firstRing+i],longitude,latitude)) { hole=true;break; }
        if (!hole) return polygon.area=="UNK"?std::string_view{}:polygon.area;
    }
    constexpr double maximum=3000.0;
    const double scale=111320.0*std::max(0.001,std::abs(std::cos(latitude*0.017453292519943295)));
    const double marginX=maximum/scale,marginY=maximum/111320.0;
    std::vector<std::pair<std::string_view,double>> distances;
    distances.reserve(8);
    for (const auto& polygon:kPolygons) {
        if (polygon.area=="UNK"||longitude<polygon.west-marginX||longitude>polygon.east+marginX||latitude<polygon.south-marginY||latitude>polygon.north+marginY) continue;
        const double distance=CoastDistanceSquared(kRings[polygon.firstRing],longitude,latitude,scale);
        const auto found=std::find_if(distances.begin(),distances.end(),[&](const auto& item){return item.first==polygon.area;});
        if (found==distances.end()) distances.emplace_back(polygon.area,distance);
        else found->second=std::min(found->second,distance);
    }
    std::string_view nearestArea;
    double nearest=maximum*maximum,runnerUp=std::numeric_limits<double>::infinity();
    for (const auto& item:distances) {
        if (item.second<nearest) {runnerUp=nearestArea.empty()?std::numeric_limits<double>::infinity():nearest;nearest=item.second;nearestArea=item.first;}
        else runnerUp=std::min(runnerUp,item.second);
    }
    if (nearestArea.empty()||std::sqrt(runnerUp)-std::sqrt(nearest)<500.0) return {};
    return nearestArea;
}
